SELECT t2.FUND_NAME AS `基金名称`, t2.FUND_SYMBOL AS `基金代码`, t1.TRADING_DAY AS `期初交易日`, t1.RESTORED_ACCU_NAV AS `期初复权净值`, t2.TRADING_DAY AS `期末交易日`, t2.RESTORED_ACCU_NAV AS `期末复权净值`, ROUND((t2.RESTORED_ACCU_NAV / NULLIF(t1.RESTORED_ACCU_NAV, 0) - 1) * 100, 2) AS `今年以来收益率(%)` FROM (SELECT FUND_SYMBOL, TRADING_DAY, RESTORED_ACCU_NAV FROM FUND_NETVALUE WHERE FUND_NAME LIKE '%中欧医疗健康混合A%' AND TRADING_DAY = (SELECT MAX(TRADING_DAY) FROM FUND_NETVALUE WHERE FUND_NAME LIKE '%中欧医疗健康混合A%' AND TRADING_DAY < '2026-01-01' AND HISVALID = 1 AND RESTORED_ACCU_NAV IS NOT NULL) AND HISVALID = 1 AND RESTORED_ACCU_NAV IS NOT NULL) t1 JOIN (SELECT FUND_NAME, FUND_SYMBOL, TRADING_DAY, RESTORED_ACCU_NAV FROM FUND_NETVALUE WHERE FUND_NAME LIKE '%中欧医疗健康混合A%' AND TRADING_DAY = '2026-09-02' AND HISVALID = 1 AND RESTORED_ACCU_NAV IS NOT NULL) t2 ON t1.FUND_SYMBOL = t2.FUND_SYMBOL ORDER BY t2.FUND_SYMBOL LIMIT 1;
